//! The `KernelProvider` backed by ggml, and the core's static build of ggml (RFC-0040 §8.1;
//! ADR-0403).
//!
//! Layer 2 in RFC-0001 §4.1. So far this crate holds what COMP-E7-T01 builds: the vendored ggml
//! tensor library and its CPU backend, linked statically (`build.rs`), the bindings
//! (`bindings.rs`, generated by `bindgen` and checked in), and a safe surface over the two
//! operations the build is checked with: [`dequantize`] and [`get_rows`]. The provider itself is
//! COMP-E7-T02's op mapping and later tasks.
//!
//! **How ggml is built.** At the baseline ISA (x86-64-v2, ARMv8.0), with floating-point
//! contraction off and every symbol hidden (ADR-0403 item 6; RFC-0042 §4.1 rule 7). It is the
//! correctness reference of ADR-0002 and the calibration baseline of ADR-0422, so it is built
//! for agreement, not speed: the CPU provider brings the speed. [`BUILD_FLAGS`] names the flags
//! this build used.
//!
//! `unsafe` is allowed in this crate (RFC-0001 §4.2 rule 8). Every `unsafe` block and impl carries
//! a `// SAFETY:` comment that states its invariant (ADR-0001 item 4).

#![deny(clippy::undocumented_unsafe_blocks)]

use std::ffi::CStr;
use std::fmt;
use std::ptr;

#[expect(
    dead_code,
    non_camel_case_types,
    unreachable_pub,
    reason = "bindgen's output, generated and checked in (bindings.rs)"
)]
mod sys {
    include!("bindings.rs");
}

/// The ggml commit this crate builds, as `third_party/ggml.lock` records it.
pub const COMMIT: &str = "a05c9922613c6a2230dbb1d0de679519ecafb4f0";

/// The flags `build.rs` gave ggml's sources on this target, beyond the include paths and
/// definitions: the baseline ISA, no contraction and hidden symbols.
pub const BUILD_FLAGS: &str = env!("SYNTROPY_GGML_FLAGS");

/// The ggml version string the build reports (`ggml_version()`).
#[must_use]
pub fn version() -> &'static str {
    // SAFETY: `ggml_version` returns a pointer to a static NUL-terminated string literal.
    let raw = unsafe { CStr::from_ptr(sys::ggml_version()) };
    raw.to_str().unwrap_or("")
}

/// The ggml commit the build reports (`ggml_commit()`).
#[must_use]
pub fn commit() -> &'static str {
    // SAFETY: `ggml_commit` returns a pointer to a static NUL-terminated string literal.
    let raw = unsafe { CStr::from_ptr(sys::ggml_commit()) };
    raw.to_str().unwrap_or("")
}

/// The ggml storage types this crate reads.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum GgmlType {
    /// 32-bit IEEE floats.
    F32,
    /// IEEE half floats.
    F16,
    /// bfloat16.
    Bf16,
    /// 32 elements: an F16 scale and 4-bit values, offset by 8.
    Q4_0,
    /// 32 elements: an F16 scale and signed 8-bit values.
    Q8_0,
    /// 256 elements in 8 sub-blocks of 32, with 6-bit sub-block scales and minimums.
    Q4K,
}

impl GgmlType {
    const fn raw(self) -> sys::ggml_type {
        match self {
            Self::F32 => sys::ggml_type::GGML_TYPE_F32,
            Self::F16 => sys::ggml_type::GGML_TYPE_F16,
            Self::Bf16 => sys::ggml_type::GGML_TYPE_BF16,
            Self::Q4_0 => sys::ggml_type::GGML_TYPE_Q4_0,
            Self::Q8_0 => sys::ggml_type::GGML_TYPE_Q8_0,
            Self::Q4K => sys::ggml_type::GGML_TYPE_Q4_K,
        }
    }

    /// The elements in one block.
    #[must_use]
    pub fn block_elems(self) -> usize {
        // SAFETY: a pure lookup in ggml's static type table, for a type it defines.
        let n = unsafe { sys::ggml_blck_size(self.raw()) };
        usize::try_from(n).expect("a block holds a positive number of elements")
    }

    /// The bytes of one block.
    #[must_use]
    pub fn block_bytes(self) -> usize {
        // SAFETY: a pure lookup in ggml's static type table, for a type it defines.
        unsafe { sys::ggml_type_size(self.raw()) }
    }

    /// The elements `bytes` bytes of this type hold, if they are whole blocks.
    fn elems_in(self, bytes: usize) -> Option<usize> {
        let block = self.block_bytes();
        bytes
            .is_multiple_of(block)
            .then(|| bytes / block * self.block_elems())
    }
}

/// The block geometry ggml's type traits give type ID `id` (`enum ggml_type`), as (elements per
/// block, bytes per block); `None` for an ID past the last type this build defines. The tests
/// check `kernels::reference`'s layouts and `manifest`'s RFC-0042 §2.1 table against it
/// (COMP-E13-T02).
#[must_use]
pub fn geometry_of_id(id: u32) -> Option<(usize, usize)> {
    if id >= sys::ggml_type::GGML_TYPE_COUNT.0 {
        return None;
    }
    let ty = sys::ggml_type(id);
    // SAFETY: pure lookups in ggml's static type table, for an ID below `GGML_TYPE_COUNT`.
    let (elems, bytes) = unsafe { (sys::ggml_blck_size(ty), sys::ggml_type_size(ty)) };
    Some((usize::try_from(elems).ok()?, bytes))
}

/// Why a call into ggml was refused before it was made, or failed.
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum GgmlError {
    /// The data is not a whole number of blocks, or not the size the call names.
    Length {
        /// The bytes given.
        bytes: usize,
        /// What they had to be a multiple of, or equal to.
        expected: usize,
    },
    /// A row length that is not a whole number of blocks.
    RowLength {
        /// The elements per row given.
        elems: usize,
        /// The type's block size.
        block: usize,
    },
    /// A row index outside the matrix.
    Row {
        /// The index.
        index: i32,
        /// The rows the matrix has.
        rows: usize,
    },
    /// ggml could not create its context.
    Init,
    /// The graph did not compute, with ggml's status.
    Compute(i32),
    /// The type has no conversion to F32 in ggml.
    NoConversion(GgmlType),
}

impl fmt::Display for GgmlError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Length { bytes, expected } => {
                write!(
                    f,
                    "{bytes} bytes is not a whole number of {expected}-byte units"
                )
            }
            Self::RowLength { elems, block } => {
                write!(
                    f,
                    "a row of {elems} elements is not a whole number of {block}-element blocks"
                )
            }
            Self::Row { index, rows } => write!(f, "row {index} is outside a {rows}-row matrix"),
            Self::Init => f.write_str("ggml could not create its context"),
            Self::Compute(status) => write!(f, "the ggml graph failed with status {status}"),
            Self::NoConversion(ty) => write!(f, "ggml has no conversion to F32 for {ty:?}"),
        }
    }
}

impl std::error::Error for GgmlError {}

/// `src` dequantised to F32 by ggml's own conversion for `ty` (its `to_float` type trait), as
/// ggml's CPU backend reads weights. `src` must be a whole number of blocks.
///
/// # Errors
///
/// [`GgmlError::Length`] when `src` is not whole blocks; [`GgmlError::NoConversion`] for `F32`,
/// which has no conversion.
pub fn dequantize(ty: GgmlType, src: &[u8]) -> Result<Vec<f32>, GgmlError> {
    let n = ty.elems_in(src.len()).ok_or(GgmlError::Length {
        bytes: src.len(),
        expected: ty.block_bytes(),
    })?;
    // SAFETY: `ggml_get_type_traits` returns a pointer into ggml's static type table, valid for
    // the program, for any type ggml defines.
    let traits = unsafe { &*sys::ggml_get_type_traits(ty.raw()) };
    let to_float = traits.to_float.ok_or(GgmlError::NoConversion(ty))?;
    let mut out = vec![0.0f32; n];
    let k = i64::try_from(n).expect("a slice's length fits in i64");
    // SAFETY: `src` holds `n / block_elems` whole blocks of `ty` and `out` has room for `n`
    // floats, which is what `to_float(x, y, k)` reads and writes.
    unsafe { to_float(src.as_ptr().cast(), out.as_mut_ptr(), k) };
    Ok(out)
}

/// ggml's `get_rows` on its CPU backend: the rows of `matrix`, a row-major matrix of `ty` with
/// `row_elems` elements per row, picked by `rows`, each converted to F32. The graph runs on one
/// thread.
///
/// # Errors
///
/// [`GgmlError::RowLength`] when `row_elems` is not whole blocks, [`GgmlError::Length`] when
/// `matrix` is not whole rows, [`GgmlError::Row`] for an index outside the matrix, and
/// [`GgmlError::Init`] or [`GgmlError::Compute`] when ggml fails.
pub fn get_rows(
    ty: GgmlType,
    matrix: &[u8],
    row_elems: usize,
    rows: &[i32],
) -> Result<Vec<f32>, GgmlError> {
    let block = ty.block_elems();
    if row_elems == 0 || !row_elems.is_multiple_of(block) {
        return Err(GgmlError::RowLength {
            elems: row_elems,
            block,
        });
    }
    let row_bytes = row_elems / block * ty.block_bytes();
    if matrix.is_empty() || !matrix.len().is_multiple_of(row_bytes) {
        return Err(GgmlError::Length {
            bytes: matrix.len(),
            expected: row_bytes,
        });
    }
    let n_rows = matrix.len() / row_bytes;
    if let Some(&index) = rows
        .iter()
        .find(|&&i| usize::try_from(i).map_or(true, |i| i >= n_rows))
    {
        return Err(GgmlError::Row {
            index,
            rows: n_rows,
        });
    }
    if rows.is_empty() {
        return Ok(Vec::new());
    }
    let out_elems = row_elems * rows.len();
    let ne0 = i64::try_from(row_elems).expect("fits");
    let ne1 = i64::try_from(n_rows).expect("fits");
    let n_idx = i64::try_from(rows.len()).expect("fits");
    // SAFETY: plain size queries with no inputs.
    let overhead = unsafe { sys::ggml_tensor_overhead() * 3 + sys::ggml_graph_overhead() };
    // The tensors' data, their headers and the graph, with room for ggml's alignment padding and
    // the compute plan's work buffer.
    let mem_size = overhead + matrix.len() + rows.len() * 4 + out_elems * 4 + (1 << 20);
    // SAFETY: `ggml_cpu_init` only builds ggml's lookup tables, once; it is safe to call again.
    unsafe { sys::ggml_cpu_init() };
    let ctx = Context::new(mem_size)?;
    // SAFETY: `ctx` is a live context with `mem_size` bytes, enough for every tensor below, so
    // each `ggml_new_tensor_*` returns a tensor whose data lies inside it. The copies write
    // exactly each tensor's `ggml_nbytes`, which equals the lengths checked above.
    unsafe {
        let a = sys::ggml_new_tensor_2d(ctx.0, ty.raw(), ne0, ne1);
        let idx = sys::ggml_new_tensor_1d(ctx.0, sys::ggml_type::GGML_TYPE_I32, n_idx);
        if a.is_null() || idx.is_null() {
            return Err(GgmlError::Init);
        }
        debug_assert_eq!(sys::ggml_nbytes(a), matrix.len());
        ptr::copy_nonoverlapping(matrix.as_ptr(), sys::ggml_get_data(a).cast(), matrix.len());
        ptr::copy_nonoverlapping(rows.as_ptr(), sys::ggml_get_data(idx).cast(), rows.len());
        let out = sys::ggml_get_rows(ctx.0, a, idx);
        let graph = sys::ggml_new_graph(ctx.0);
        if out.is_null() || graph.is_null() {
            return Err(GgmlError::Init);
        }
        sys::ggml_build_forward_expand(graph, out);
        let status = sys::ggml_graph_compute_with_ctx(ctx.0, graph, 1);
        if status != sys::ggml_status::GGML_STATUS_SUCCESS {
            return Err(GgmlError::Compute(status.0));
        }
        debug_assert_eq!(sys::ggml_nbytes(out), out_elems * 4);
        let mut result = vec![0.0f32; out_elems];
        ptr::copy_nonoverlapping(sys::ggml_get_data_f32(out), result.as_mut_ptr(), out_elems);
        Ok(result)
    }
}

/// A ggml context, freed on drop.
struct Context(*mut sys::ggml_context);

impl Context {
    fn new(mem_size: usize) -> Result<Self, GgmlError> {
        let params = sys::ggml_init_params {
            mem_size,
            mem_buffer: ptr::null_mut(),
            no_alloc: false,
        };
        // SAFETY: with a null `mem_buffer`, ggml allocates `mem_size` bytes itself and returns
        // null if it cannot; the context is freed once, on drop.
        let ctx = unsafe { sys::ggml_init(params) };
        if ctx.is_null() {
            Err(GgmlError::Init)
        } else {
            Ok(Self(ctx))
        }
    }
}

impl Drop for Context {
    fn drop(&mut self) {
        // SAFETY: `self.0` came from `ggml_init` and is freed only here.
        unsafe { sys::ggml_free(self.0) };
    }
}
